css:
@page { size: A4 landscape; margin: 0; }
* { box-sizing: border-box; }
body { margin: 0; padding: 12mm; font-family: DejaVu Sans, sans-serif; color: #243a30; background: #fff; }
.passport-sheet { width: 273mm; height: 186mm; margin: 0 auto; padding: 8mm; position: relative; overflow: hidden; border: 2px solid #78957f; border-radius: 3mm; background: #f4f6e9; }
.passport-header { display: flex; justify-content: space-between; align-items: center; padding: 3mm 4mm; color: #174f3a; border-bottom: 1px solid #a8baa6; text-align: center; font-size: 14px; }
.passport-header span, .emblem span { font-size: 9px; }
.emblem { border: 1px solid #78957f; border-radius: 2mm; padding: 2mm; width: 75mm; color: #286549; font-size: 13px; }
.identity { display: flex; gap: 7mm; direction: ltr; padding: 7mm 2mm 3mm; height: 112mm; }
.photo { width: 42mm; height: 55mm; border: 1px solid #87958a; display: flex; align-items: center; justify-content: center; color: #87958a; overflow: hidden; background: #e7ebdf; }
.photo img { width: 100%; height: 100%; object-fit: cover; }
.fields { direction: rtl; flex: 1; display: grid; grid-template-columns: 1fr 1fr 1fr; align-content: start; gap: 5mm 6mm; }
.field { border-bottom: 1px solid #c9d2c7; padding-bottom: 2mm; min-height: 12mm; }
.field label { display: block; color: #387353; font-size: 8px; }
.field b, .field span { display: block; font-size: 10px; }
.field span { direction: ltr; text-align: right; }
.authority { position: absolute; left: 54mm; right: 10mm; bottom: 37mm; border-top: 1px solid #c9d2c7; padding-top: 2mm; display: flex; justify-content: space-between; font-size: 9px; }
.signature { position: absolute; right: 12mm; bottom: 27mm; width: 58mm; height: 18mm; text-align: center; font-size: 8px; color: #52665a; }
.signature img { display:block; max-height: 12mm; max-width: 48mm; margin: 0 auto 1mm; object-fit: contain; }
.mrz { direction: ltr; text-align: left; font-family: DejaVu Sans Mono, monospace; font-size: 10px; letter-spacing: 1px; line-height: 1.8; background: #edf0e6; border-top: 2px solid #78957f; position: absolute; left: 8mm; right: 8mm; bottom: 8mm; padding: 2mm 4mm; overflow: hidden; white-space: nowrap; }
footer { position: absolute; left: 10mm; bottom: 30mm; max-width: 120mm; text-align: left; color: #a42c25; font-size: 8px; font-weight: bold; }
